// Telefonpolicy flyttet til «Varsel-digest (hver 6. time)» 2026-11-19: digesten sender kl. 06/12/18
// (aldri 23-06) og slår sammen like varsler. Her filtreres bare det som aldri skal på telefonen.
const out = [];
for (const it of $input.all()) {
  const raw = JSON.stringify((it.json && it.json.body) || {});
  /* NYENHET_INGEN_PUSH: nye enheter (NetAlertX) logges og går i dagsrapporten, aldri på telefonen */
  if (/new device|ny enhet/i.test(raw)) continue;
  out.push(it);
}
return out;
